const output = $('Normalize AI Output').first().json.output;

const articleHtml = output.article_html;

const image1Candidates = $('HTTP Request6').all().map(item => item.json);
const image2Candidates = $('HTTP Request11').all().map(item => item.json);

const sourceData = $('Edit Fields').first().json;

const sourceName =
  sourceData.source ||
  output.source_name ||
  'Izvor';

const sourceUrl =
  sourceData.url ||
  output.source_url ||
  null;

const image1SearchTerms = [
  output.tags?.[1],
  output.tags?.[0],
  output.focus_keyword
].filter(Boolean);

const image2SearchTerms = [
  output.tags?.[2],
  output.tags?.[3],
  output.focus_keyword
].filter(Boolean);


const relevantInternalLinkHtml =
  $('Pick Relevant Internal Link').first().json.relevant_internal_link_html || '';

const getImageUrl = (media) =>
  media?.source_url ||
  media?.guid?.rendered ||
  null;
const getMediaText = (media) =>
  [
    media?.title?.rendered,
    media?.alt_text,
    media?.caption?.rendered,
    media?.description?.rendered,
    media?.slug,
    media?.source_url,
    media?.guid?.rendered
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

const normalizeText = (value) =>
  String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'dj')
    .replace(/ć/g, 'c')
    .replace(/č/g, 'c')
    .replace(/š/g, 's')
    .replace(/ž/g, 'z');

const scoreMedia = (media, searchTerms, usedUrls = []) => {
  const url = getImageUrl(media);

  if (!url) return -9999;
  if (usedUrls.includes(url)) return -9999;

  const text = normalizeText(getMediaText(media));
  let score = 0;

  for (const term of searchTerms) {
    const normalizedTerm = normalizeText(term);

    if (!normalizedTerm) continue;

    if (text.includes(normalizedTerm)) {
      score += 50;
    }

    const words = normalizedTerm.split(/\s+/).filter(Boolean);

    for (const word of words) {
      if (word.length > 2 && text.includes(word)) {
        score += 10;
      }
    }
  }

  if (media?.alt_text) score += 8;
  if (media?.caption?.rendered) score += 5;
  if (media?.description?.rendered) score += 3;

  const title = normalizeText(media?.title?.rendered || '');
  const slug = normalizeText(media?.slug || '');
  const source = normalizeText(url);

  if (title.includes('chatgpt') || slug.includes('chatgpt') || source.includes('chatgpt')) {
    score -= 30;
  }

  if (title.includes('screenshot') || slug.includes('screenshot') || source.includes('screenshot')) {
    score -= 10;
  }

  if (media?.date) {
    const timestamp = new Date(media.date).getTime();
    if (!Number.isNaN(timestamp)) {
      score += Math.min(10, timestamp / 1000000000000);
    }
  }

  return score;
};

const pickBestImage = (candidates, searchTerms, usedUrls = []) => {
  const validCandidates = candidates.filter(media => getImageUrl(media));

  if (!validCandidates.length) {
    return null;
  }

  return validCandidates
    .map(media => ({
      media,
      score: scoreMedia(media, searchTerms, usedUrls)
    }))
    .sort((a, b) => b.score - a.score)[0].media;
};

const escapeHtml = (value) =>
  String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

const cleanText = (value) =>
  String(value || '')
    .replace(/<[^>]*>/g, '')
    .replace(/"/g, '&quot;')
    .trim();

const getAlt = (media, fallback) =>
  cleanText(
    media?.alt_text ||
    media?.title?.rendered ||
    fallback
  );

const image1 = pickBestImage(image1Candidates, image1SearchTerms);
const image1Url = getImageUrl(image1);

const image2 = pickBestImage(image2Candidates, image2SearchTerms, [image1Url]);
const image2Url = getImageUrl(image2);

if (!articleHtml) {
  throw new Error('Nedostaje article_html iz Basic LLM Chain.');
}

if (!image1Url) {
  throw new Error('Nedostaje URL prve slike.');
}

if (!image2Url) {
  throw new Error('Nedostaje URL druge slike.');
}

const figure1 = `
<figure class="wp-block-image size-full">
  <img src="${escapeHtml(image1Url)}" alt="${getAlt(image1, 'Stanija Dobrojević')}" />
</figure>`;

const figure2 = `
<figure class="wp-block-image size-full">
  <img src="${escapeHtml(image2Url)}" alt="${getAlt(image2, 'Asmin Durdžić')}" />
</figure>`;

// Pronalaženje svih završetaka pasusa
const paragraphMatches = [...articleHtml.matchAll(/<\/p>/gi)];

if (paragraphMatches.length < 3) {
  throw new Error(
    `Članak ima samo ${paragraphMatches.length} pasusa. Potrebna su najmanje 3.`
  );
}

// Prva slika ide posle drugog pasusa
const firstInsertPosition =
  paragraphMatches[1].index + paragraphMatches[1][0].length;

let finalHtml =
  articleHtml.slice(0, firstInsertPosition) +
  figure1 +
  articleHtml.slice(firstInsertPosition);

// Relevantan interni link ide posle prve slike
if (relevantInternalLinkHtml && !finalHtml.includes(relevantInternalLinkHtml)) {
  const figure1Position = finalHtml.indexOf(figure1) + figure1.length;

  finalHtml =
    finalHtml.slice(0, figure1Position) +
    relevantInternalLinkHtml +
    finalHtml.slice(figure1Position);
}

// Ponovo računamo pasuse nakon prve slike i relevantnog linka
const updatedParagraphs = [...finalHtml.matchAll(/<\/p>/gi)];

// Druga slika ide pre poslednjeg pasusa
const lastParagraphEndIndex =
  updatedParagraphs[updatedParagraphs.length - 1].index;

const lastParagraphStartIndex =
  finalHtml.lastIndexOf('<p', lastParagraphEndIndex);

if (lastParagraphStartIndex === -1) {
  throw new Error('Nije pronađen početak poslednjeg pasusa.');
}

finalHtml =
  finalHtml.slice(0, lastParagraphStartIndex) +
  figure2 +
  finalHtml.slice(lastParagraphStartIndex);

// Spoljni link ka izvoru ide poslednji
if (sourceUrl && !finalHtml.includes(sourceUrl)) {
  const sourceParagraph = `
<p class="article-source">
  Izvor: <a href="${escapeHtml(sourceUrl)}" target="_blank" rel="noopener noreferrer">${escapeHtml(sourceName)}</a>
</p>`;

  finalHtml += sourceParagraph;
}

return [
  {
    json: {
      article_html_with_images: finalHtml,
      image_1_url: image1Url,
      image_2_url: image2Url,
      source_name: sourceName,
      source_url: sourceUrl,
      source_link_inserted: Boolean(sourceUrl),
      relevant_internal_link_inserted: Boolean(relevantInternalLinkHtml),
      images_inserted: true
    }
  }
];

