const currentPostId = 12361;

const posts = $input.all().map(item => item.json);

const cleanText = (value) =>
  String(value || '')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&#8211;/g, '–')
    .replace(/&#8222;/g, '„')
    .replace(/&#8220;/g, '“')
    .replace(/&#8221;/g, '“')
    .replace(/&quot;/g, '"')
    .replace(/&#038;/g, '&')
    .replace(/&amp;/g, '&')
    .trim();

const escapeHtml = (value) =>
  String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

const relevantPost = posts.find(post =>
  post.id !== currentPostId &&
  post.link &&
  post.title?.rendered
);

if (!relevantPost) {
  return [
    {
      json: {
        relevant_internal_link_html: '',
        relevant_internal_link_found: false
      }
    }
  ];
}

const title = cleanText(relevantPost.title.rendered);
const link = relevantPost.link;

const relevantInternalLinkHtml =
  `<p class="internal-link relevant-link">Pročitajte i: <a href="${escapeHtml(link)}">${escapeHtml(title)}</a></p>`;

return [
  {
    json: {
      relevant_internal_link_html: relevantInternalLinkHtml,
      relevant_internal_link_found: true,
      relevant_internal_link_title: title,
      relevant_internal_link_url: link,
      relevant_internal_link_id: relevantPost.id
    }
  }
];

const input = $input.first().json;

let raw =
  input.output ??
  input.text ??
  input.response ??
  input.result ??
  input.content ??
  input.message;

let data;

function cleanCodeFence(value) {
  return String(value || '')
    .replace(/^\s*```json\s*/i, '')
    .replace(/^\s*```\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

function onlyJsonObject(value) {
  const text = cleanCodeFence(value);
  const firstBrace = text.indexOf('{');
  const lastBrace = text.lastIndexOf('}');

  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error('AI nije vratio JSON objekat.');
  }

  return text.slice(firstBrace, lastBrace + 1);
}

function decodeJsonLikeString(value) {
  const text = String(value || '');

  try {
    return JSON.parse('"' + text.replace(/\n/g, '\\n') + '"');
  } catch (error) {
    return text
      .replace(/\\"/g, '"')
      .replace(/\\n/g, '\n')
      .replace(/\\r/g, '')
      .replace(/\\t/g, ' ')
      .trim();
  }
}

function serbianQuotes(value) {
  let open = true;

  return String(value || '').replace(/"/g, () => {
    const mark = open ? '„' : '“';
    open = !open;
    return mark;
  });
}

function extractString(rawText, field, nextField) {
  const regex = new RegExp(
    `"${field}"\\s*:\\s*"([\\s\\S]*?)"\\s*,\\s*"${nextField}"\\s*:`
  );

  const match = rawText.match(regex);

  if (!match) {
    return '';
  }

  return decodeJsonLikeString(match[1]);
}

function extractArray(rawText, field, nextField = null) {
  let regex;

  if (nextField) {
    regex = new RegExp(
      `"${field}"\\s*:\\s*(\\[[\\s\\S]*?\\])\\s*,\\s*"${nextField}"\\s*:`
    );
  } else {
    regex = new RegExp(
      `"${field}"\\s*:\\s*(\\[[\\s\\S]*?\\])`
    );
  }

  const match = rawText.match(regex);

  if (!match) {
    return [];
  }

  const arrayText = match[1];

  try {
    return JSON.parse(arrayText);
  } catch (error) {
    return [...arrayText.matchAll(/"([^"]+)"/g)]
      .map(item => item[1].trim())
      .filter(Boolean);
  }
}

if (raw && typeof raw === 'object') {
  data = raw.output && typeof raw.output === 'object'
    ? raw.output
    : raw;
} else {
  raw = onlyJsonObject(raw);

  try {
    let parsed = JSON.parse(raw);

    if (typeof parsed === 'string') {
      parsed = JSON.parse(parsed);
    }

    data = parsed.output && typeof parsed.output === 'object'
      ? parsed.output
      : parsed;
  } catch (error) {
    data = {
      headline: extractString(raw, 'headline', 'seo_title'),
      seo_title: extractString(raw, 'seo_title', 'meta_description'),
      meta_description: extractString(raw, 'meta_description', 'slug'),
      slug: extractString(raw, 'slug', 'category'),
      category: extractString(raw, 'category', 'tags'),
      tags: extractArray(raw, 'tags', 'focus_keyword'),
      focus_keyword: extractString(raw, 'focus_keyword', 'article_html'),
      article_html: extractString(raw, 'article_html', 'internal_link_suggestions'),
      internal_link_suggestions: extractArray(raw, 'internal_link_suggestions')
    };
  }
}

if (!Array.isArray(data.tags)) {
  data.tags = String(data.tags || '')
    .split(',')
    .map(tag => tag.trim())
    .filter(Boolean);
}

if (!Array.isArray(data.internal_link_suggestions)) {
  data.internal_link_suggestions = String(data.internal_link_suggestions || '')
    .split(',')
    .map(item => item.trim())
    .filter(Boolean);
}

data.headline = serbianQuotes(data.headline);
data.seo_title = serbianQuotes(data.seo_title);
data.meta_description = serbianQuotes(data.meta_description);
data.focus_keyword = serbianQuotes(data.focus_keyword);

data.slug = String(data.slug || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/đ/g, 'dj')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');

const requiredFields = [
  'headline',
  'seo_title',
  'meta_description',
  'slug',
  'category',
  'tags',
  'focus_keyword',
  'article_html',
  'internal_link_suggestions',
];

for (const field of requiredFields) {
  if (!(field in data)) {
    throw new Error(`Nedostaje obavezno polje: ${field}`);
  }
}

if (!data.article_html) {
  throw new Error('Nedostaje article_html.');
}

return [
  {
    json: {
      output: {
        headline: String(data.headline || ''),
        seo_title: String(data.seo_title || ''),
        meta_description: String(data.meta_description || ''),
        slug: data.slug,
        category: String(data.category || ''),
        tags: data.tags,
        focus_keyword: String(data.focus_keyword || ''),
        article_html: String(data.article_html || ''),
        internal_link_suggestions: data.internal_link_suggestions,
      }
    }
  }
];

const tagId = $json.body?.[0]?.id;

const postId =
  $json.post_id ||
  $('Attach Post Context').first().json.post_id ||
  $('Create Draft Post').first().json.id;

if (!tagId) {
  throw new Error('Nije pronađen postojeći tag ID u body[0].id');
}

if (!postId) {
  throw new Error('Nije pronađen post_id za tag granu.');
}

return {
  json: {
    post_id: Number(postId),
    tag_id: Number(tagId)
  }
};

const items = $input.all();

const postId = items[0]?.json?.post_id;

if (!postId) {
  throw new Error('Nedostaje post_id u tag grani.');
}

const tagIds = items
  .map(item => Number(item.json.tag_id))
  .filter(id => Number.isInteger(id) && id > 0);

const uniqueTagIds = [...new Set(tagIds)];

if (!uniqueTagIds.length) {
  throw new Error('Nema tag ID-jeva za agregaciju.');
}

return [
  {
    json: {
      post_id: Number(postId),
      tag_ids: uniqueTagIds
    }
  }
];

const output = $('Normalize AI Output').first().json.output;
const postId = $json.id;

if (!postId) {
  throw new Error('Nedostaje post ID iz Create Draft Post.');
}

if (!output?.tags?.length) {
  throw new Error('Nedostaju tagovi iz Normalize AI Output.');
}

return {
  json: {
    post_id: Number(postId),
    output
  }
};

const output = $('Normalize AI Output').first().json.output;
const sourceData = $('Edit Fields').first().json;

const headline = String(output.headline || '');
const focusKeyword = String(output.focus_keyword || '');
const topic = String(sourceData.topic || '');
const sourceText = String(sourceData.source_text || '');

const tags = Array.isArray(output.tags) ? output.tags : [];

function clean(value) {
  return String(value || '')
    .replace(/[„“"']/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const knownRealityPeople = [
  'Stanija Dobrojević',
  'Maja Marinković',
  'Asmin Durdžić',
  'Aneli Ahmić',
  'Janjuš',
  'Marko Janjušević Janjuš',
  'Kristijan Golubović',
  'Uroš Stanić',
  'Ena Čolić',
  'Jovan Pejić Peja',
  'Milica Mitrović',
  'Željko Mitrović',
  'Anđela Ranković',
  'Anđelo Ranković',
  'Tara Simov',
  'Bora Santana'
];

const combinedText = `${headline} ${focusKeyword} ${topic} ${tags.join(' ')} ${sourceText}`;

const detectedPeople = knownRealityPeople
  .filter(name => combinedText.toLowerCase().includes(name.toLowerCase()));

const mainPeople = detectedPeople.slice(0, 3);

let query1;
let query2;
let featuredQuery;

if (mainPeople.length >= 2) {
  featuredQuery = `${mainPeople[0]} ${mainPeople[1]}`;
  query1 = `${mainPeople[0]} Zadruga Elita`;
  query2 = `${mainPeople[1]} Zadruga Elita`;
} else if (mainPeople.length === 1) {
  featuredQuery = `${mainPeople[0]} Zadruga Elita`;
  query1 = `${mainPeople[0]} Instagram`;
  query2 = `${mainPeople[0]} Pink Zadruga`;
} else {
  featuredQuery = clean(focusKeyword || topic || headline);
  query1 = clean(tags[0] || topic || headline);
  query2 = clean(tags[1] || focusKeyword || topic || headline);
}

return {
  json: {
    ...$json,
    image_search: {
      main_people: mainPeople,
      featured_query: clean(featuredQuery),
      inline_query_1: clean(query1),
      inline_query_2: clean(query2),
      fallback_query: clean(`${focusKeyword} ${tags.slice(0, 2).join(' ')}`)
    }
  }
};

const imageSearchData = $('Prepare Image Search Queries').first().json;
const mediaItems = Array.isArray($json) ? $json : ($json.body || []);

const results = Array.isArray(mediaItems)
  ? mediaItems
  : [];

const query = imageSearchData.image_search?.featured_query || '';

if (!results.length) {
  return {
    json: {
      ...imageSearchData,
      featured_image_found: false,
      featured_image_id: null,
      featured_image_url: null,
      featured_image_query: query
    }
  };
}

function scoreImage(item) {
  const title = String(item.title?.rendered || item.title || '').toLowerCase();
  const alt = String(item.alt_text || '').toLowerCase();
  const caption = String(item.caption?.rendered || '').toLowerCase();
  const sourceUrl = String(item.source_url || '');

  let score = 0;

  const queryWords = query
    .toLowerCase()
    .split(/\s+/)
    .filter(word => word.length > 2);

  for (const word of queryWords) {
    if (title.includes(word)) score += 5;
    if (alt.includes(word)) score += 4;
    if (caption.includes(word)) score += 2;
    if (sourceUrl.toLowerCase().includes(word)) score += 1;
  }

  if (item.media_type === 'image') score += 10;
  if (sourceUrl.match(/\.(jpg|jpeg|png|webp)$/i)) score += 5;

  return score;
}

const ranked = results
  .map(item => ({
    item,
    score: scoreImage(item)
  }))
  .sort((a, b) => b.score - a.score);

const best = ranked[0]?.item;

if (!best?.id) {
  return {
    json: {
      ...imageSearchData,
      featured_image_found: false,
      featured_image_id: null,
      featured_image_url: null,
      featured_image_query: query
    }
  };
}

return {
  json: {
    ...imageSearchData,
    featured_image_found: true,
    featured_image_id: best.id,
    featured_image_url: best.source_url || null,
    featured_image_query: query,
    featured_image_title: best.title?.rendered || ''
  }
};
